using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10-12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves, drizzle with olive oil, and serve."
                ],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and black pepper in a bowl.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Pour egg mixture over pasta, tossing quickly to create a creamy sauce. Add pasta water as needed."
                ],
                AverageRating = 4.8, RatingCount = 25
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                    "Grill or broil chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger in oil until softened.",
                    "Add spices (cumin, turmeric, garam masala) and cook for 1 minute.",
                    "Add tomato sauce and simmer for 15 minutes.",
                    "Stir in cream and cooked chicken. Simmer 5 more minutes and serve with rice."
                ],
                AverageRating = 4.7, RatingCount = 18
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Biryani", Category = "Indian",
                Description = "Fragrant basmati rice layered with spiced mixed vegetables.",
                Ingredients = ["Basmati rice", "Mixed vegetables", "Onion", "Yogurt", "Saffron", "Mint leaves", "Ghee", "Biryani masala"],
                Steps = [
                    "Soak basmati rice for 30 minutes, then parboil until 70% cooked.",
                    "Fry sliced onions in ghee until golden brown.",
                    "Cook vegetables with biryani masala and yogurt.",
                    "Layer rice and vegetables in a heavy-bottomed pot.",
                    "Top with saffron milk and fried onions.",
                    "Seal the pot and cook on low heat (dum) for 25 minutes."
                ],
                AverageRating = 4.3, RatingCount = 9
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                AverageRating = 4.2, RatingCount = 15
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh avocado dip with lime, cilantro, and a kick of jalapeño.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit the avocados, scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Mix in diced onion, jalapeño, tomato, and chopped cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                AverageRating = 4.6, RatingCount = 20
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich, warm chocolate cake with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Grease and flour ramekins.",
                    "Melt chocolate and butter together, stir until smooth.",
                    "Whisk eggs, sugar, and vanilla until thick and pale.",
                    "Fold chocolate mixture into the egg mixture, then fold in flour.",
                    "Divide batter among ramekins.",
                    "Bake for 12-14 minutes — edges should be firm but center soft.",
                    "Invert onto plates and serve immediately."
                ],
                AverageRating = 4.9, RatingCount = 30
            },
            new Recipe
            {
                Id = 8, Title = "Miso Soup", Category = "Japanese",
                Description = "A comforting Japanese soup with tofu, seaweed, and scallions.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Scallions"],
                Steps = [
                    "Bring dashi stock to a gentle simmer.",
                    "Rehydrate wakame seaweed in water, then drain.",
                    "Cut tofu into small cubes.",
                    "Dissolve miso paste in a ladleful of warm dashi, then stir back into the pot.",
                    "Add tofu and wakame, heat gently (do not boil).",
                    "Serve in bowls topped with sliced scallions."
                ],
                AverageRating = 4.4, RatingCount = 11
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
        {
            _ratings[recipeId] = [];
        }

        _ratings[recipeId].Add(stars);

        var totalRatings = recipe.RatingCount + _ratings[recipeId].Count;
        var totalSum = (recipe.AverageRating * recipe.RatingCount) + _ratings[recipeId].Sum();
        recipe.AverageRating = Math.Round(totalSum / totalRatings, 1);
        recipe.RatingCount = totalRatings;
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

