@page "/categories"
@page "/categories/{CategoryName}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (string.IsNullOrEmpty(CategoryName))
{
    <PageTitle>Browse Categories — RecipeHub</PageTitle>

    <h1>Browse Recipe Categories</h1>
    <p class="text-muted">Select a category to explore recipes.</p>

    <div class="list-group">
        @foreach (var category in RecipeService.GetCategories())
        {
            var recipes = RecipeService.GetRecipesByCategory(category);
            <a href="categories/@category" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                <span class="fw-bold">@category</span>
                <span class="badge bg-primary rounded-pill">@recipes.Count</span>
            </a>
        }
    </div>
}
else
{
    var recipes = RecipeService.GetRecipesByCategory(CategoryName);

    <PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item active" aria-current="page">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="card-text">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                    <small class="text-muted">(@recipe.AverageRating / @recipe.RatingCount ratings)</small>
                                </span>
                                <a href="recipe/@recipe.Id" class="btn btn-sm btn-outline-primary">View Recipe</a>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public string? CategoryName { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeHub.Services
@inject RecipeService RecipeService

@if (recipe is null)
{
    <PageTitle>Recipe Not Found — RecipeHub</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@recipe.Title — RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="categories/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@recipe.Title</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@recipe.Title</h1>
            <p class="lead text-muted">@recipe.Description</p>

            <StarRating RecipeId="recipe.Id" CurrentRating="recipe.AverageRating" RatingCount="recipe.RatingCount" @rendermode="InteractiveServer" />

            <hr />

            <h3>🧾 Ingredients</h3>
            <ul class="list-group list-group-flush mb-4">
                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>

            <h3>📝 Steps</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>

        <div class="col-lg-4">
            <div class="card shadow-sm">
                <div class="card-body">
                    <h5 class="card-title">Recipe Info</h5>
                    <dl>
                        <dt>Category</dt>
                        <dd><a href="categories/@recipe.Category">@recipe.Category</a></dd>
                        <dt>Ingredients</dt>
                        <dd>@recipe.Ingredients.Count items</dd>
                        <dt>Steps</dt>
                        <dd>@recipe.Steps.Count steps</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

