<div class="my-3">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star-rating @(star <= hoverRating ? "star-hover" : star <= (int)Math.Round(CurrentRating) ? "star-filled" : "star-empty")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button"
              title="Rate @star star(s)">
            @(star <= (hoverRating > 0 ? hoverRating : (int)Math.Round(CurrentRating)) ? "★" : "☆")
        </span>
    }
    <small class="text-muted ms-2">@CurrentRating / 5 (@RatingCount ratings)</small>
    @if (submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverRating;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

.star-rating {
    font-size: 1.5rem;
    cursor: pointer;
    transition: transform 0.1s;
    user-select: none;
}

.star-rating:hover {
    transform: scale(1.2);
}

.star-filled {
    color: #ffc107;
}

.star-hover {
    color: #ffdb4d;
}

.star-empty {
    color: #dee2e6;
}

.category-card:hover {
    transform: translateY(-4px);
    transition: transform 0.2s;
    border-color: #0d6efd;
}

